// Nome do Projeto: blink_com_gemini
// Microcontrolador: Arduino UNO R3
// Nome de Usuário: Francis

// --- Definição dos Pinos dos LEDs ---
const int ledPin1 = 2; // LED conectado ao pino digital 2
const int ledPin2 = 3; // LED conectado ao pino digital 3
const int ledPin3 = 4; // LED conectado ao pino digital 4

// --- Variáveis para controle de tempo do LED 1 ---
// Estado atual do LED (HIGH para ligado, LOW para desligado)
int ledState1 = LOW;
// Variável para armazenar o último momento em que o LED 1 foi atualizado
unsigned long previousMillis1 = 0;
// Intervalo para o LED 1: ligado por 300ms, desligado por 700ms (total 1000ms por ciclo)
const long intervalOn1 = 300;
const long intervalOff1 = 700;
long currentInterval1 = intervalOff1; // Começa desligado

// --- Variáveis para controle de tempo do LED 2 ---
int ledState2 = LOW;
unsigned long previousMillis2 = 0;
// Intervalo para o LED 2: ligado por 500ms, desligado por 500ms (total 1000ms por ciclo)
const long intervalOn2 = 500;
const long intervalOff2 = 500;
long currentInterval2 = intervalOff2;

// --- Variáveis para controle de tempo do LED 3 ---
int ledState3 = LOW;
unsigned long previousMillis3 = 0;
// Intervalo para o LED 3: ligado por 800ms, desligado por 200ms (total 1000ms por ciclo)
const long intervalOn3 = 800;
const long intervalOff3 = 200;
long currentInterval3 = intervalOff3;

void setup() {
  // Configura os pinos dos LEDs como SAÍDA
  pinMode(ledPin1, OUTPUT);
  pinMode(ledPin2, OUTPUT);
  pinMode(ledPin3, OUTPUT);
}

void loop() {
  // Obtém o tempo atual em milissegundos desde o início do programa
  unsigned long currentMillis = millis();

  // --- Lógica para o LED 1 ---
  // Verifica se passou o tempo definido para o estado atual do LED 1
  if (currentMillis - previousMillis1 >= currentInterval1) {
    previousMillis1 = currentMillis; // Salva o tempo atual

    // Inverte o estado do LED
    if (ledState1 == LOW) {
      ledState1 = HIGH;
      currentInterval1 = intervalOn1; // Próximo intervalo será o de "ligado"
    } else {
      ledState1 = LOW;
      currentInterval1 = intervalOff1; // Próximo intervalo será o de "desligado"
    }

    // Escreve o novo estado no pino do LED
    digitalWrite(ledPin1, ledState1);
  }

  // --- Lógica para o LED 2 ---
  if (currentMillis - previousMillis2 >= currentInterval2) {
    previousMillis2 = currentMillis;

    if (ledState2 == LOW) {
      ledState2 = HIGH;
      currentInterval2 = intervalOn2;
    } else {
      ledState2 = LOW;
      currentInterval2 = intervalOff2;
    }

    digitalWrite(ledPin2, ledState2);
  }

  // --- Lógica para o LED 3 ---
  if (currentMillis - previousMillis3 >= currentInterval3) {
    previousMillis3 = currentMillis;

    if (ledState3 == LOW) {
      ledState3 = HIGH;
      currentInterval3 = intervalOn3;
    } else {
      ledState3 = LOW;
      currentInterval3 = intervalOff3;
    }

    digitalWrite(ledPin3, ledState3);
  }
}
